refsection.programlisting:
F = gf_create_field(2, 4);
alpha = [0 1 0 0];
gf_power(F, alpha, 4)      // [1 1 0 0]: alpha^4 = 1 + alpha
gf_power(F, alpha, 15)     // [1 0 0 0]: alpha^15 = 1
gf_to_exponential(F, gf_power(F, alpha, 100))   // 10, ya que 100 = 6*15 + 10

P = gf_create_field(7, 1);
gf_power(P, 1:6, 3)        // [1 1 6 1 6 6]
